function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function mapRowTag(raw: TransactionListRow['rowTag']): RowTag {
  if (raw === 'GroupTotal') return 'GroupTotal';
  if (raw === 'GrandTotal') return 'GrandTotal';
  return 'Detail';
}

function normalizeItems(items: TransactionListRow[]): TransactionListRow[] {
  const mapped = items.map(r => {
    const rowTag = mapRowTag(r.rowTag);
    return {
      ...r,
      rowTag,
      isBold: Boolean(r.isBold) || rowTag !== 'Detail',
      amount: Number(r.amount ?? 0),
      amountFc: Number(r.amountFc ?? 0),
    };
  });
  // Prefer BE UX order; if GrandTotal first (legacy Ftag), move one GrandTotal to end.
  const grandIdx = mapped.findIndex(r => mapRowTag(r.rowTag) === 'GrandTotal');
  if (grandIdx === 0 && mapped.filter(r => mapRowTag(r.rowTag) === 'GrandTotal').length === 1) {
    const [grand] = mapped.splice(grandIdx, 1);
    mapped.push(grand);
  }
  return mapped;
}

function omitEmpty(params: Record<string, string | number | boolean | undefined>) {
  const out: Record<string, string | number | boolean | undefined> = {};
  Object.entries(params).forEach(([k, v]) => {
    if (v === undefined || v === null) return;
    // groupBy explicit "" = tắt GroupTotal — phải gửi API (omit → default TK_NO).
    if (typeof v === 'string' && v.trim() === '' && k !== 'groupBy') return;
    out[k] = typeof v === 'string' && k !== 'groupBy' ? v.trim() : v;
  });
  return out;
}

